<?php
namespace App\Http\Controllers;
use App\Models\PaymentTransaction; use App\Models\Donation; use App\Services\AuditLogger; use Illuminate\Http\Request;
class PaymentWebhookController extends Controller { public function handle(Request $request){$signature=$request->header('X-Payment-Signature');$secret=(string)config('services.payment.webhook_secret',env('PAYMENT_WEBHOOK_SECRET'));$raw=$request->getContent();abort_unless($secret && $signature && hash_equals(hash_hmac('sha256',$raw,$secret),$signature),401);$data=$request->validate(['provider'=>'required|string|max:50','reference'=>'required|string|max:150','status'=>'required|string|max:30','amount'=>'nullable|numeric','currency'=>'nullable|string|max:3']);$tx=PaymentTransaction::updateOrCreate(['reference'=>$data['reference']],['provider'=>$data['provider'],'status'=>$data['status'],'amount'=>$data['amount']??0,'currency'=>$data['currency']??'NGN','payload'=>$request->all()]);if($tx->donation_id && in_array($data['status'],['success','completed'],true)){Donation::whereKey($tx->donation_id)->update(['status'=>'completed']);}AuditLogger::record('payment.webhook','Payment webhook processed',$tx);return response()->json(['received'=>true]);}}
